import { readFileSync } from "node:fs";
import { join } from "node:path";
import { buildMatrix, parseEvidenceBundle, type DeviceCapabilities, type EvidenceBundle, type MatrixOperation, type OperationVerdict } from "@busforge/product";

// The evidence bundle generated by tools/evidence-bundle.ts. Read once and validated on first use;
// an invalid bundle fails every request that needs it rather than showing a matrix it cannot back.
let bundle: EvidenceBundle | undefined;
export function evidenceBundle(): EvidenceBundle {
  bundle ??= parseEvidenceBundle(JSON.parse(readFileSync(join(import.meta.dir, "evidence-bundle.json"), "utf8")));
  return bundle;
}

// One device's row: its own Product with the capabilities it has now, next to the bundled Products
// that may back `derived` or the same-application hint.
export function deviceCompatibility(productRef: string, appProgramId: string, capabilities: DeviceCapabilities): Record<MatrixOperation, OperationVerdict> {
  const b = evidenceBundle();
  const others = b.products.filter((p) => p.productRef !== productRef || p.appProgramId !== appProgramId);
  return buildMatrix(b.records, [{ productRef, appProgramId, capabilities }, ...others])[0].operations;
}
